	return newError(C.av_channel_layout_copy(dst, l.c))
}

func (l ChannelLayout) clone() (ChannelLayout, error) {
	var cl C.AVChannelLayout
	err := l.copy(&cl)
	dst := newChannelLayoutFromC(&cl)
	return dst, err
}
