	// Get planes
	planes, err := d.f.planes(b, align)
	if err != nil {
		return fmt.Errorf("astiav: getting planes failed: %w", err)
	}

	// Copy planes
	if err := d.f.copyPlanes(planes); err != nil {
		return fmt.Errorf("astiav: copying planes failed: %w", err)
	}
	return nil
