func (d *FrameData) fromImagePix(pix []uint8, stride int) error {
	// Copy planes
	if err := d.f.copyPlanes([]frameDataPlane{{bytes: pix, linesize: stride}}); err != nil {
		return fmt.Errorf("astiav: copying planes failed: %w", err)
	}
	return nil
