func (d *FrameData) FromImage(src image.Image) error {
	// Copy planes
	switch v := src.(type) {
	case *image.Alpha:
		return d.fromImagePix(v.Pix, v.Stride)
	case *image.Alpha16:
		return d.fromImagePix(v.Pix, v.Stride)
	case *image.CMYK:
		return d.fromImagePix(v.Pix, v.Stride)
	case *image.Gray:
		return d.fromImagePix(v.Pix, v.Stride)
	case *image.Gray16:
		return d.fromImagePix(v.Pix, v.Stride)
	case *image.NRGBA:
		return d.fromImagePix(v.Pix, v.Stride)
	case *image.NRGBA64:
		return d.fromImagePix(v.Pix, v.Stride)
	case *image.NYCbCrA:
		return d.fromImageYCbCrA(v.Y, v.Cb, v.Cr, v.A, v.YStride, v.CStride, v.AStride)
	case *image.RGBA:
		return d.fromImagePix(v.Pix, v.Stride)
	case *image.RGBA64:
		return d.fromImagePix(v.Pix, v.Stride)
	case *image.YCbCr:
