// 编码器的参数必须与输出流保持一致
encCtx.SetBitRate(128000) // 设置比特率为 128kbps (128000 bits/second)。这个值会影响音质和文件大小。
encCtx.SetSampleRate(ostream.CodecParameters().SampleRate())
